parameters.text:
={{ (() => {
  // The brief for the AI; it finds its sources itself with web search
  const options = $('Set your options').first().json;
  return 'Topic: ' + String($('The request').first().json.topic ?? '').trim() + '\n'
    + 'Length: about ' + options.articleLength + ' words\n'
    + 'Use at least ' + options.minSources + ' reliable sources.';
})() }}

assignments.value:
={{ (() => {
  // The AI answers in HTML: a language comment, the title in <h1>, the body, and last the list of sources
  const safely = read => { try { return read(); } catch (error) { return undefined; } };
  const answer = safely(() => $('Research and write').first().json) ?? {};
  const options = $('Set your options').first().json;
  // The AI answers with text; some models send a list of text blocks, and some wrap it in a code fence
  const text = value => typeof value === 'string' ? value
    : Array.isArray(value) ? value.map(part => typeof part === 'string' ? part : part?.text ?? '').join('') : '';
  const html = text(answer.output).trim().replace(/^```(?:html)?\s*/i, '').replace(/\s*```$/, '').trim();
  const code = ((html.match(/<!--\s*language:\s*([a-z]{2})/i) || [])[1] || '').toLowerCase();
  const language = ["en", "es", "de", "fr", "it", "pt", "nl", "sv", "da", "no", "fi", "bg"].includes(code) ? code : 'en';
  const title = ((html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i) || [])[1] || '').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
  // The sources section starts at the last <h2>; its links are the sources
  const start = html.lastIndexOf('<h2');
  const tail = start >= 0 ? html.slice(start) : '';
  const sources = [...tail.matchAll(/<a\s[^>]*href="(https?:\/\/[^"]+)"[^>]*>([\s\S]*?)<\/a>/gi)]
    .map(link => ({ url: link[1], title: link[2].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim() || link[1] }));
  const sourcesHeading = ((tail.match(/<h2[^>]*>([\s\S]*?)<\/h2>/i) || [])[1] || 'Sources').replace(/<[^>]+>/g, '').trim();
  const bodyStart = html.search(/<\/h1>/i);
  const bodyHtml = (sources.length ? html.slice(bodyStart >= 0 ? bodyStart + 5 : 0, start) : html.slice(bodyStart >= 0 ? bodyStart + 5 : 0))
    .replace(/<!--[\s\S]*?-->/g, '').trim();
  let problem = '';
  if (answer.error) problem = 'the writer stopped with an error: ' + String(answer.error.message ?? answer.error).slice(0, 200);
  else if (/^NOT ENOUGH SOURCES/i.test(html.replace(/<!--[\s\S]*?-->/g, '').trim()) || !html) problem = 'the search did not find enough reliable information';
  else if (!title || bodyHtml.replace(/<[^>]+>/g, '').trim().length < 200) problem = 'the answer had no article in it';
  else if (sources.length < options.minSources) problem = 'the article lists ' + sources.length + ' of the ' + options.minSources + ' sources it needs';
  return { ok: !problem, problem, language, title, bodyHtml, sources, sourcesHeading };
})() }}

parameters.text:
={{ (() => {
  // Plain text for Lenz: the title, then the body without HTML
  const article = $('Read the article').first().json.article;
  return (article.title + '\n\n' + article.bodyHtml)
    .replace(/<\/(p|h2|h3|li)>/gi, '\n')   // keep sentences apart
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"')
    .replace(/[ \t]+/g, ' ')
    .replace(/\s*\n\s*/g, '\n')
    .trim();
})() }}

parameters.responseText:
={{ (() => {
  // Nothing was written: why, and what to try
  // A web page: headings, paragraphs and lists; & < > escaped
  const esc = value => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const fmt = text => {
    const out = [];
    let list = false;
    String(text ?? '').split('\n').forEach((line, index) => {
      const item = /^- /.test(line), more = /^  \S/.test(line);
      if (list && !item && !more) { out.push('</ul>'); list = false; }
      if (index === 0) out.push('<h2>' + esc(line) + '</h2>');
      else if (/^(FOUND BY LENZ|FIXED IN THE DRAFT|STILL WORTH A LOOK|LENZ COULD NOT CHECK THIS DRAFT|REWRITTEN ON YOUR NOTE|THE EDIT DID NOT WORK|YOUR OWN EDITS|NO ARTICLE THIS TIME)/.test(line)) out.push('<h3>' + esc(line) + '</h3>');
      else if (item) { if (!list) { out.push('<ul>'); list = true; } out.push('<li>' + esc(line.slice(2))); }
      else if (more && list) out.push('<br>' + esc(line.trim()));
      else if (line.trim()) out.push('<p>' + esc(line) + '</p>');
    });
    if (list) out.push('</ul>');
    return out.join('').replace(/(<li>[\s\S]*?)(?=<li>|<\/ul>)/g, '$1</li>');
  };
  // n8n shows a closing page's HTML on a bare page, so it brings its own card, in the colours of the form
  const card = html => '<style>body{margin:0;background:#fbfcfe;font-family:"Open Sans",sans-serif}'
    + '.lenz-page{max-width:448px;margin:24px auto;padding:24px;background:#fff;border:1px solid #dbdfe7;border-radius:8px;'
    + 'color:#555;font-size:14px;line-height:1.5}.lenz-page h2{margin:0 0 12px;text-align:center;font-size:20px;color:#222}'
    + '.lenz-page h3{margin:16px 0 6px;font-size:14px;color:#222}.lenz-page ul{padding-left:20px}.lenz-page li{margin:4px 0}</style>'
    + '<div class="lenz-page">' + html + '</div>';
  return card(fmt('No article this time\nNothing was saved: ' + $('Read the article').first().json.article.problem + '. Try a more specific topic.'));
})() }}

parameters.text:
={{ (() => {
  // Send only the first N claims to Assess, so one long article can't use up your credits
  const claims = $('List the claims (free)').first().json.identified_claims ?? [];
  return claims.slice(0, $('Set your options').first().json.maxClaims).join('\n');
})() }}

assignments.value:
={{ (() => {
  // A red flag is a claim Assess rates false, or passes with low confidence. The first ones, up to your limit, get a deep check
  const claims = $('Check the claims').first().json.claims ?? [];
  const limit = Math.max(0, Number($('Set your options').first().json.maxDeepChecks) || 0);
  return claims.filter(claim => claim.passed === false || claim.confidence === 'low').slice(0, limit);
})() }}

conditions.leftValue:
={{ (() => {
  // One clean result per deep check, also when a check failed or ran out of time
  const deepChecks = () => {
    if (!$('Deep-check the red flags').isExecuted) return [];
    const sent = $('One item per red flag').all();
    return $('Deep-check the red flags').all().map((item, index) => {
      const result = item.json ?? {};
      // Written out on purpose: inside this long expression n8n returned undefined for sent[index]?.json.claim (12863, 12869)
      const picked = sent[index] && sent[index].json ? sent[index].json : {};
      return {
        claim: picked.claim || '',
        status: result.status || 'failed',
        passed: result.passed === true,
        verdict: result.verdict ?? '',
        confidence: result.confidence ?? '',
        score: result.lenz_score ?? 0,
        summary: result.executive_summary ?? '',
        source: (result.citations ?? [])[0]?.url ?? '',
        verificationId: result.verification_id ?? '',
        note: result.message || (typeof result.error === 'string' ? result.error : result.error?.message) || ''
      };
    });
  };
  // A problem is confirmed only by a finished deep check that does not pass
  return deepChecks().some(result => result.status === 'completed' && result.passed === false);
})() }}

