={{ (() => {
  // The article as it is saved: corrected if Lenz confirmed a problem, with its sources at the end
  const article = $('Read the article').first().json.article;
  // What the fix changed: the AI answered with the whole article; a broken or cut-off answer is never used
  const fixed = $('Fix the flagged claims').isExecuted ? (() => {
  // The fix: compare the article before and after, part by part
  const safely = read => { try { return read(); } catch (error) { return undefined; } };
  const answer = safely(() => $('Fix the flagged claims').first().json) ?? {};
  const before = String(safely(() => $('Read the article').first().json.article.bodyHtml) ?? '');
  // The AI answers with text; some models send a list of text blocks, and some wrap it in a code fence
  const text = value => typeof value === 'string' ? value
    : Array.isArray(value) ? value.map(part => typeof part === 'string' ? part : part?.text ?? '').join('') : '';
  const raw = text(answer.output ?? answer.text).trim().replace(/^```(?:html)?\s*/i, '').replace(/\s*```$/, '').trim();
