    .replace(/<head[\s\S]*?<\/head>/gi, '').replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<!--[\s\S]*?-->/g, '')
    .replace(/(<\/(?:p|h[1-6]|li|blockquote|table|figure)>)/gi, '$1␞')
    .split('␞')
    .map(part => ({
      text: decode(part.replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim(),
      heading: /<h[1-6][\s>]/i.test(part),
      source: /^\s*(<[uo]l[^>]*>\s*)?<li[^>]*>\s*(<[^a][^>]*>\s*)*<a\s[^>]*>[\s\S]*?<\/a>(\s*<\/[^>]+>)*\s*<\/li>\s*$/i.test(part)
    }))
    .filter(part => part.text);
