      if (gone.length || fresh.length) changes.push({
        // The parts of one change stay apart, so a new heading does not run into its first paragraph
        before: gone.map(part => part.text).join(' / '),
        after: fresh.map(part => part.text).join(' / '),
        sources: [...gone, ...fresh].every(part => part.source)
      });
      gone = []; fresh = [];
    };
    let i = 0, j = 0;
    while (i < old.length || j < now.length) {
      if (i < old.length && j < now.length && old[i].text === now[j].text) { close(); i++; j++; }
      else if (j < now.length && (i === old.length || same[i][j + 1] >= same[i + 1][j])) { fresh.push(now[j]); added.push(now[j]); j++; }
      else { gone.push(old[i]); i++; }
    }
    close();
    // Lenz checks each new or changed part on its own, at most 8 to protect your credits.
    // Headings, source links and very short parts are not claims, so they are left out.
    const checks = added.filter(part => !part.heading && !part.source && part.text.length >= 20).map(part => ({ text: part.text }));
