  const size = list => list.reduce((sum, part) => sum + part.text.length, 0);
  // An answer that is broken or cut off never replaces the article
  let problem = '';
  if (answer.error) problem = 'the AI stopped with an error: ' + String(answer.error.message ?? answer.error).slice(0, 200);
  else if (!now.length) problem = 'the answer had no article in it';
  else if (!/<\/(p|ul|ol|h[1-6]|li|blockquote|table|figure)>\s*$/i.test(html)) problem = 'the answer stops in the middle';
  else if (size(now) < size(old) * 0.3) problem = 'the answer is much shorter than the article, so part of it may be missing';
  if (problem) return { ok: false, problem, language, html: '', changes: [], checks: [], unchecked: 0 };
  return { ok: true, problem: '', language, html, ...compare(old, now) };
})() : null;
  const fix = fixed;
  const safe = text => String(text ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  const list = article.sources.map(source => '<li><a href="' + safe(source.url) + '">' + safe(source.title) + '</a></li>').join('');
  return (fix?.ok ? fix.html : article.bodyHtml) + '\n<h2>' + safe(article.sourcesHeading) + '</h2>\n<ul>' + list + '</ul>';
})() }}

={{ (() => {
  // checked, no_claims, or not_checked when Lenz could not be reached (both Lenz steps pass their errors on)
