  const listed = safely(() => $('List the claims (free)').first().json);
  const assess = $('Check the claims').isExecuted ? safely(() => $('Check the claims').first().json) : undefined;
  if (!listed || listed.error || !assess || assess.error) return 'not_checked';
  return (assess.claims ?? []).length ? 'checked' : 'no_claims';
})() }}

={{ (() => {
  // The report for the editor: what Lenz found and fixed, what still needs a human look, and what looks right
  const safely = read => { try { return read(); } catch (error) { return undefined; } };
  const plural = (n, word) => n + ' ' + word + (n === 1 ? '' : 's');
  const cut = (text, max) => {
    // Cut at the end of a sentence where possible
    const clean = String(text ?? '').replace(/\s+/g, ' ').trim();
    if (clean.length <= max) return clean;
    const part = clean.slice(0, max);
    const end = Math.max(part.lastIndexOf('. '), part.lastIndexOf('! '), part.lastIndexOf('? '));
    return end > max * 0.4 ? part.slice(0, end + 1) : part.replace(/\s+\S*$/, '') + '...';
  };
