  const listed = safely(() => $('List the claims (free)').first().json);
  const assess = $('Check the claims').isExecuted ? safely(() => $('Check the claims').first().json) : undefined;
  if (!listed || listed.error || !assess || assess.error) {
    return article.title + '\nLENZ COULD NOT CHECK THIS DRAFT\nCheck the facts yourself before publishing.';
  }
  const claims = assess.claims ?? [];
  const lines = [article.title, plural(article.sources.length, 'source') + ' used, ' + plural(claims.length, 'claim') + ' checked by Lenz.'];
  if (!claims.length) {
    lines.push('Lenz found no checkable factual claims in this draft.');
    return lines.join('\n');
  }
  // Deep checks, each one with the claim it checked
