        verdict: result.verdict ?? '',
        confidence: result.confidence ?? '',
        score: result.lenz_score ?? 0,
        summary: result.executive_summary ?? '',
        source: (result.citations ?? [])[0]?.url ?? '',
        verificationId: result.verification_id ?? '',
        note: result.message || (typeof result.error === 'string' ? result.error : result.error?.message) || ''
      };
    });
  };
  const results = deepChecks();
  const sent = results.map(result => result.claim);
  const confirmed = results.filter(result => result.status === 'completed' && result.passed === false);
  const cleared = results.filter(result => result.status === 'completed' && result.passed === true && result.confidence !== 'low');
  const shaky = results.filter(result => result.status === 'completed' && result.passed === true && result.confidence === 'low');
  const unfinished = results.filter(result => result.status !== 'completed');
  // What the fix changed: the AI answered with the whole article; a broken or cut-off answer is never used
  const fixed = $('Fix the flagged claims').isExecuted ? (() => {
  // The fix: compare the article before and after, part by part
  const safely = read => { try { return read(); } catch (error) { return undefined; } };
  const answer = safely(() => $('Fix the flagged claims').first().json) ?? {};
  const before = String(safely(() => $('Read the article').first().json.article.bodyHtml) ?? '');
  // The AI answers with text; some models send a list of text blocks, and some wrap it in a code fence
  const text = value => typeof value === 'string' ? value
    : Array.isArray(value) ? value.map(part => typeof part === 'string' ? part : part?.text ?? '').join('') : '';
  const raw = text(answer.output ?? answer.text).trim().replace(/^```(?:html)?\s*/i, '').replace(/\s*```$/, '').trim();
  const language = ((raw.match(/<!--\s*language:\s*([a-z]{2})/i) || [])[1] || '').toLowerCase();
