    while (end < a.length - start && end < b.length - start && a[a.length - 1 - end] === b[b.length - 1 - end]) end++;
    const middle = list => { const part = list.slice(start, list.length - end).join(' '); return part && (start ? '... ' : '') + part + (end ? ' ...' : ''); };
