  const answers = $('Check my edits').isExecuted ? $('Check my edits').all().map(item => item.json) : [];
  const claims = answers.flatMap(answer => answer.claims ?? []);
  const shaky = claims.filter(claim => claim.passed === false || claim.confidence === 'low');
