      const item = /^- /.test(line), more = /^  \S/.test(line);
      if (list && !item && !more) { out.push('</ul>'); list = false; }
      if (index === 0) out.push('<h2>' + esc(line) + '</h2>');
      else if (/^(FOUND BY LENZ|FIXED IN THE DRAFT|STILL WORTH A LOOK|LENZ COULD NOT CHECK THIS DRAFT|REWRITTEN ON YOUR NOTE|THE EDIT DID NOT WORK|YOUR OWN EDITS|NO ARTICLE THIS TIME)/.test(line)) out.push('<h3>' + esc(line) + '</h3>');
